function cypressTree(seed){
  const r = rng(seed), W = geoBuf(), L = geoBuf(), H = 19, R0 = 1.75, y0 = 1.1, up = V3(0, 1, 0);
  const env = t => R0*Math.pow(Math.sin(Math.PI*Math.min(1, 0.12 + t*0.95)), 0.75)*(1 - 0.3*t) + 0.15;   // widest a third of the way up, a pointed tip
  const tp = []; for (let i=0;i<=8;i++){ const t = i/8; tp.push(V3(perlin(t*2 + seed, 1.3)*0.15*t, t*H*0.94, perlin(t*2 + seed, 4.1)*0.15*t)); }
  tubeInto(W, tp, tp.map((_, i) => 0.34*(1 - 0.8*i/8) + 0.03), 8, { ao:i => 0.6 + 0.05*i, vScale:2.5 });
  for (let b=0;b<14;b++){ const t = 0.08 + b/14*0.8, a = b*2.39996, o = V3(0, y0 + t*(H - y0)*0.9, 0), d = V3(Math.cos(a)*0.45, 0.9, Math.sin(a)*0.45).normalize();
    tubeInto(W, [o, o.clone().addScaledVector(d, env(t)*1.1)], [0.08, 0.025], 5, { ao:() => 0.55 }); }
  const n = Math.round(620*Q.cardK);
  for (let k=0;k<n;k++){
    const t = Math.pow(r(), 0.85), a = r()*TAU, e = env(t), dep = 0.45 + 0.55*Math.sqrt(r()), y = y0 + t*(H - y0);
    const out = V3(Math.cos(a), 0, Math.sin(a)), p = V3(out.x*e*dep, y, out.z*e*dep);
    const ax = out.clone().multiplyScalar(0.55).add(V3(0, 1, 0)).add(V3(r() - 0.5, r() - 0.5, r() - 0.5).multiplyScalar(0.5)).normalize();
    const side = V3().crossVectors(ax, out).normalize(), sz = (0.9 + 0.6*r())*(1 - 0.35*t);
    const b0 = p.clone().addScaledVector(ax, -sz*0.45), cs = [b0.clone().addScaledVector(side, -sz/2), b0.clone().addScaledVector(side, sz/2), b0.clone().addScaledVector(side, sz/2).addScaledVector(ax, sz), b0.clone().addScaledVector(side, -sz/2).addScaledVector(ax, sz)];
    const cell = (r()*4)|0, u0 = (cell%2)*0.5, v0 = Math.floor(cell/2)*0.5, uv = [[u0,v0+0.5],[u0+0.5,v0+0.5],[u0+0.5,v0],[u0,v0]];
    const nrm = out.clone().multiplyScalar(0.7).addScaledVector(up, 0.45 + 0.3*t).normalize(), ao = (0.5 + 0.6*dep*dep)*(0.85 + 0.3*t), j = 0.88 + 0.24*r(), base = L.P.length/3;
    for (let q=0;q<4;q++){ L.P.push(cs[q].x, cs[q].y, cs[q].z); L.N.push(nrm.x, nrm.y, nrm.z); L.UV.push(uv[q][0], uv[q][1]); L.C.push(ao*j*0.95, ao*j, ao*j*0.9); }
    L.I.push(base, base+1, base+2, base, base+2, base+3);
  }
  const wood = geoFinish(W), leaf = geoFinish(L), box = new THREE.Box3().copy(wood.boundingBox).union(leaf.boundingBox);
  const S = Math.max(box.max.x, -box.min.x, box.max.z, -box.min.z)*2*1.04, Ht = box.max.y*1.03;
  return { wood, leaf, S:Math.max(S, Ht), H:Ht };
}

